mapper.select:
select v.* from (select hm.bp_id manufacturer_id, hm.bp_name manufacturer_id_n, hbm.bp_id factory_id, hbm.bp_name factory_id_n, (select yt.max_term from yh_factory_delay_term yt where yt.manufacturer_id = hm.bp_id and yt.factory_id = hbm.bp_id) max_term, (select yt.note from yh_factory_delay_term yt where yt.manufacturer_id = hm.bp_id and yt.factory_id = hbm.bp_id) note, (select yt.term_id from yh_factory_delay_term yt where yt.manufacturer_id = hm.bp_id and yt.factory_id = hbm.bp_id) term_id from hls_bp_master hm, hls_bp_master_relation hbr, hls_bp_master hbm where exists (select * from hls_bp_master_role hr where hr.bp_id = hm.bp_id and hr.bp_category in ('MANUFACTURER','PARTNER')) and hm.bp_id = hbr.related_bp_id and hbr.relation_type = 'MANUFACTURER' and hbr.bp_id = hbm.bp_id and exists (select * from hls_bp_master_role hr where hr.bp_id = hbm.bp_id and hr.bp_category = 'VENDER') union select hm.bp_id manufacturer_id, hm.bp_name manufacturer_id_n, null factory_id, null factory_id_n, (select yt.max_term from yh_factory_delay_term yt where yt.manufacturer_id = hm.bp_id) max_term, (select yt.note from yh_factory_delay_term yt where yt.manufacturer_id = hm.bp_id) note, (select yt.term_id from yh_factory_delay_term yt where yt.manufacturer_id = hm.bp_id) term_id from hls_bp_master hm where exists (select * from hls_bp_master_role hr where hr.bp_id = hm.bp_id and hr.bp_category in ('MANUFACTURER','PARTNER')) and not exists (select * from hls_bp_master_relation hbr, hls_bp_master hbm where hbr.related_bp_id = hm.bp_id and hbr.relation_type = 'MANUFACTURER' and hbr.bp_id = hbm.bp_id and exists (select * from hls_bp_master_role hr where hr.bp_id = hbm.bp_id and hr.bp_category = 'VENDER'))) v
and v.manufacturer_id_n like concat(concat('%',#{manufacturerIdN}),'%')
and v.factory_id_n like concat(concat('%',#{factoryIdN}),'%')
and v.manufacturer_id = #{manufacturerId}
and v.factory_id = #{factoryId}
order by v.manufacturer_id,v.factory_id
